/**
 * Broad, domain-diverse "representative" eval slice, generated by combining
 * ~20 different tech domains with per-category phrasing templates. Purpose:
 * make sure the hand-crafted core/stress sets (which skew toward generic
 * web/JS examples) don't leave the eval accidentally narrow to one stack —
 * the classifier needs to generalize across languages and domains, not
 * pattern-match on "React" or "Node".
 *
 * Deterministic (no randomness) so results are reproducible across runs.
 */
import type { EvalPrompt } from "./prompts"

