function pushIf(list: EvalPrompt[], id: string, message: string, expected: EvalPrompt["expected"], recentContext?: string): void {
  list.push({ id, message, expected, recentContext, set: "representative" })
}

function generate(): EvalPrompt[] {
  const out: EvalPrompt[] = []
  let n = 0

  for (const d of DOMAINS) {
    const tag = d.id
    // quick (6 templates)
    pushIf(out, `g-${tag}-q1`, `Fix the typo in the comment above ${d.func} in ${d.file}.`, "quick")
    pushIf(out, `g-${tag}-q2`, `Rename the ${d.varName} variable to ${d.varName2} in ${d.file}.`, "quick")
    pushIf(out, `g-${tag}-q3`, `What's the correct way to ${d.smallSyntaxQuestion} in ${d.lang}?`, "quick")
    pushIf(out, `g-${tag}-q4`, `Can you run the formatter on ${d.file}? The indentation is inconsistent.`, "quick")
    // A dependency bump — even "just" a patch version — carries unknown
    // transitive/breaking-change risk that a true one-liner doesn't, so this
    // is standard, not quick (confirmed by Jev disagreeing, confidently and
    // consistently across every domain, with my original "quick" label here).
    pushIf(out, `g-${tag}-q5`, `Bump ${d.depName} to the latest patch version in ${d.label}.`, "standard")
    pushIf(out, `g-${tag}-q6`, `Add a one-line comment above ${d.func} explaining what it returns.`, "quick")

    // standard (6 templates)
    pushIf(out, `g-${tag}-s1`, `Add ${d.featureNoun} to ${d.label}.`, "standard")
    pushIf(out, `g-${tag}-s2`, `There's a bug in ${d.func} — ${d.bugSymptom}. Looks like a clear cause, please fix it.`, "standard")
    pushIf(out, `g-${tag}-s3`, `Write tests for ${d.func} in ${d.file}, covering the normal case and a couple of edge cases.`, "standard")
    pushIf(out, `g-${tag}-s4`, `Can you explain how ${d.func} in ${d.file} works?`, "standard")
    pushIf(out, `g-${tag}-s5`, `Refactor ${d.func} to ${d.smallRefactorGoal}.`, "standard")
    pushIf(out, `g-${tag}-s6`, `Why is ${d.func} slow? Just want a first look, haven't profiled it yet.`, "standard")

    // heavy (6 templates)
    pushIf(out, `g-${tag}-h1`, `We need to redesign ${d.label}'s ${d.bigSubsystem} — help plan the architecture without breaking ${d.constraint}.`, "heavy")
    pushIf(out, `g-${tag}-h2`, `${d.func} has an issue that survived one fix attempt already — help me actually track down the real cause this time.`, "heavy", "A first attempted fix for this did not resolve the underlying issue.")
    pushIf(out, `g-${tag}-h3`, `Design the ${d.securityTopic} approach for ${d.label}, considering ${d.securityConcern}.`, "heavy")
    pushIf(out, `g-${tag}-h4`, `This refactor of the ${d.bigSubsystem} touches ${d.fileCountPhrase} — plan the approach before we start changing anything.`, "heavy")
    pushIf(out, `g-${tag}-h5`, `We're seeing an intermittent production issue in ${d.label} that I can't reproduce locally — help me figure out how to diagnose it.`, "heavy")
    pushIf(out, `g-${tag}-h6`, `Optimize ${d.func} — it's become too slow for the scale we're at now and a quick tweak hasn't been enough.`, "heavy")

    // review (6 templates)
    pushIf(out, `g-${tag}-r1`, `Here's my implementation of ${d.featureNoun} in ${d.label} — can you review it before I merge?`, "review")
    pushIf(out, `g-${tag}-r2`, `I just finished ${d.func}, self-review it for bugs before I ship.`, "review")
    pushIf(out, `g-${tag}-r3`, `Audit ${d.label}'s ${d.securityTopic} handling for common issues.`, "review")
    pushIf(out, `g-${tag}-r4`, `Does this diff handle the case where ${d.edgeCase} correctly?`, "review", `User pasted a diff touching ${d.func} in ${d.file}.`)
    pushIf(out, `g-${tag}-r5`, `Check whether this change to ${d.func} introduces any regressions.`, "review", `User pasted the full new version of ${d.func}.`)
    pushIf(out, `g-${tag}-r6`, `Take a look at this PR for ${d.label} and tell me if the error handling is solid.`, "review")

    n += 24
  }

  return out
}

export const GENERATED_PROMPTS: EvalPrompt[] = generate()
